"use client"

import { motion } from "motion/react"
import { MotionIcon } from "../motion-icon"
import { BaseIconProps } from "../types"

/**
 * Chart Icon
 * Visual: Three ascending bars with axes + fill effect
 * Animation: Bars grow from bottom with spring physics
 */
export function ChartIcon({ size = 20, isActive = false, ...props }: BaseIconProps) {
  return (
    <MotionIcon size={size} isActive={isActive} aria-label="Chart" {...props}>
      {/* Y-axis */}
      <line x1="4" y1="20" x2="4" y2="4" strokeWidth="1.5" />

      {/* X-axis */}
      <line x1="4" y1="20" x2="20" y2="20" strokeWidth="1.5" />

      {/* Bar 1 (shortest) - with fill */}
      <motion.rect
        x="7"
        y="14"
        width="3"
        height="6"
        rx="0.5"
        fill="currentColor"
        fillOpacity="0.15"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{ type: "spring", stiffness: 300, damping: 15, delay: 0 }}
      />

      <motion.rect
        x="7"
        y="14"
        width="3"
        height="6"
        rx="0.5"
        fill="none"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{ type: "spring", stiffness: 300, damping: 15, delay: 0 }}
      />

      {/* Bar 2 (medium) - with fill */}
      <motion.rect
        x="12"
        y="10"
        width="3"
        height="10"
        rx="0.5"
        fill="currentColor"
        fillOpacity="0.15"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 15,
          delay: 0.04,
        }}
      />

      <motion.rect
        x="12"
        y="10"
        width="3"
        height="10"
        rx="0.5"
        fill="none"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 15,
          delay: 0.04,
        }}
      />

      {/* Bar 3 (tallest) - with fill */}
      <motion.rect
        x="17"
        y="7"
        width="3"
        height="13"
        rx="0.5"
        fill="currentColor"
        fillOpacity="0.15"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 15,
          delay: 0.08,
        }}
      />

      <motion.rect
        x="17"
        y="7"
        width="3"
        height="13"
        rx="0.5"
        fill="none"
        variants={{
          idle: { scaleY: 1 },
          hover: { scaleY: 1.25 },
          active: { scaleY: 1.15 },
        }}
        style={{ originY: 1, originX: 0.5 }}
        transition={{
          type: "spring",
          stiffness: 300,
          damping: 15,
          delay: 0.08,
        }}
      />
    </MotionIcon>
  )
}

"use client"

import { motion, useReducedMotion } from "motion/react"
import { MotionIconProps } from "./types"
import { iconVariants } from "./icon-variants"
import { cn } from "@/lib/utils"

/**
 * Base MotionIcon wrapper component
 *
 * Wraps all animated icons with:
 * - Consistent sizing and viewBox
 * - Accessibility support (reduced motion)
 * - Shared animation states (idle/hover/active)
 * - Proper SVG attributes for crisp rendering
 *
 * @example
 * ```tsx
 * <MotionIcon variants={iconVariants.bounce}>
 *   <path d="..." />
 * </MotionIcon>
 * ```
 */
export function MotionIcon({
  size = 20,
  isActive = false,
  variants,
  strokeWidth = 1.5,
  children,
  className,
  ...props
}: MotionIconProps) {
  const shouldReduceMotion = useReducedMotion()

  // Use no animation variant if user prefers reduced motion
  const effectiveVariants = shouldReduceMotion ? iconVariants.none : variants

  return (
    <motion.svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      initial="idle"
      whileHover={shouldReduceMotion ? undefined : "hover"}
      animate={isActive ? "active" : "idle"}
      variants={effectiveVariants}
      className={cn(
        "inline-block flex-shrink-0",
        // Ensure crisp rendering
        "will-change-transform",
        className
      )}
      {...props}
      // Accessibility
      role={props.role || "img"}
      aria-hidden={props["aria-label"] ? undefined : "true"}
    >
      {children}
    </motion.svg>
  )
}

import { Variants } from "motion/react"

/**
 * Easing functions for icon animations
 * All timings are optimized for 18-24px icon sizes
 */
export const iconEasing = {
  /** Default easing for most hover states - cubic bezier */
  default: [0.25, 0.1, 0.25, 1] as const,

  /** Fast, decisive easing for active/pressed states */
  active: [0.4, 0, 0.2, 1] as const,

  /** Smooth exit animation */
  exit: [0.4, 0, 1, 1] as const,

  /** Spring physics for organic motion */
  spring: { type: "spring" as const, stiffness: 300, damping: 20 },
} as const

/**
 * Shared animation variants for icon components
 * Each variant defines idle, hover, and active states
 */
export const iconVariants = {
  /**
   * Scale with subtle rotation
   * Best for: Dialogs, Buttons, Cards
   */
  popRotate: {
    idle: { scale: 1, rotate: 0 },
    hover: {
      scale: 1.1,
      rotate: 5,
      transition: { duration: 0.2, ease: iconEasing.default },
    },
    active: {
      scale: 1.05,
      rotate: 0,
      transition: { duration: 0.15, ease: iconEasing.active },
    },
  } satisfies Variants,

  /**
   * Vertical bounce effect
   * Best for: Alerts, Notifications, Badges
   */
  bounce: {
    idle: { y: 0 },
    hover: {
      y: -2,
      transition: { duration: 0.15, ease: iconEasing.default },
    },
    active: {
      y: 0,
      transition: { duration: 0.1, ease: iconEasing.exit },
    },
  } satisfies Variants,

  /**
   * Pulse animation with scale and opacity
   * Best for: Active states, Command palette
   */
  pulse: {
    idle: { scale: 1, opacity: 1 },
    hover: {
      scale: [1, 1.1, 1],
      opacity: [1, 0.8, 1],
      transition: { duration: 0.3, ease: iconEasing.default },
    },
    active: {
      scale: 1,
      opacity: [1, 0.9, 1],
      transition: {
        duration: 1.5,
        repeat: Infinity,
        ease: "easeInOut",
      },
    },
  } satisfies Variants,

  /**
   * Depth press effect (3D button press)
   * Best for: Buttons, Checkboxes, Interactive elements
   */
  press: {
    idle: { y: 0, scale: 1 },
    hover: {
      y: 0,
      scale: 1.05,
      transition: { duration: 0.2, ease: iconEasing.default },
    },
    active: {
      y: 1,
      scale: 0.98,
      transition: { duration: 0.1, ease: iconEasing.active },
    },
  } satisfies Variants,

  /**
   * Horizontal slide motion
   * Best for: Navigation, Breadcrumbs, Context menus
   */
  slideRight: {
    idle: { x: 0 },
    hover: {
      x: 2,
      transition: { duration: 0.2, ease: iconEasing.default },
    },
    active: {
      x: 0,
      transition: { duration: 0.15, ease: iconEasing.exit },
    },
  } satisfies Variants,

  /**
   * Gentle scale up
   * Best for: Avatars, Images, Media components
   */
  scaleUp: {
    idle: { scale: 1 },
    hover: {
      scale: 1.15,
      transition: { duration: 0.2, ease: iconEasing.default },
    },
    active: {
      scale: 1.1,
      transition: { duration: 0.15, ease: iconEasing.active },
    },
  } satisfies Variants,

  /**
   * Rotation effect
   * Best for: Collapsible, Accordions, Dropdowns
   */
  rotate180: {
    idle: { rotate: 0 },
    hover: {
      rotate: 180,
      transition: { duration: 0.3, ease: iconEasing.default },
    },
    active: {
      rotate: 180,
      transition: { duration: 0.25, ease: iconEasing.active },
    },
  } satisfies Variants,

  /**
   * No animation (instant transition)
   * Used when prefers-reduced-motion is enabled
   */
  none: {
    idle: {},
    hover: {},
    active: {},
  } satisfies Variants,
} as const

/**
 * Animation configuration constants
 */
export const ANIMATION_CONFIG = {
  /** Base duration for most animations */
  baseDuration: 0.15,

  /** Hover state duration */
  hoverDuration: 0.2,

  /** Active/pressed state duration */
  activeDuration: 0.1,

  /** Default stroke width */
  defaultStrokeWidth: 1.5,

  /** Active stroke width */
  activeStrokeWidth: 2,

  /** Minimum scale factor */
  minScale: 0.9,

  /** Maximum scale factor */
  maxScale: 1.15,

  /** Maximum rotation in degrees */
  maxRotation: 15,

  /** Maximum translation in pixels */
  maxTranslate: 3,
} as const
